INSERT INTO USER_ROLES (
       USER_ID
     , ROLE_ID
     , PROCESS_TIMESTAMP
     , STATUS
     , EFFECTIVE_DATE
     , FIRST_REGISTER_BRANCH
     , FIRST_REGISTER_USER
     , FIRST_REGISTER_DATE
     , FIRST_REGISTER_TIME
     , LAST_CHANGE_BRANCH
     , LAST_CHANGE_USER
     , LAST_CHANGE_DATE
     , LAST_CHANGE_TIME
) VALUES (
       #{userID}
     , #{roleId}
     , now()
     , NULLIF(#{status}, '')
     , NULLIF(#{effectiveDate}, '')
     , #{firstRegisterBranch}
     , #{firstRegisterUser}
     , #{firstRegisterDate}
     , #{firstRegisterTime}
     , #{lastChangeBranch}
     , #{lastChangeUser}
     , #{lastChangeDate}
     , #{lastChangeTime}
)

mapper.delete:

DELETE FROM USER_ROLES
 WHERE USER_ID = #{userID}
   AND ROLE_ID = #{roleId}
